permission_denials.command:
uv run --with pyyaml --with jsonschema python3 -c "
import yaml, json, jsonschema, sys
raw = open('journals/2026-08-19-chaos-flag-injected-503s.md').read()
fm = raw.split('---',2)[1]
doc = yaml.safe_load(fm)
schema = json.load(open('.claude/skills/investigate/journal.schema.json'))
jsonschema.Draft202012Validator(schema).validate(doc)
print('SCHEMA: valid')
ev = {e['id'] for e in doc['evidence']}
hyp = {h['id']: h for h in doc['hypotheses']}
bad = []
for h in doc['hypotheses']:
    for r in h['evidence_for'] + h['evidence_against']:
        if r not in ev: bad.append((h['id'], r))
for l in doc.get('latent_findings', []):
    for r in l['evidence']:
        if r not in ev: bad.append(('latent', r))
rc = doc['root_cause']['hypothesis']
print('REFS:', 'all resolve' if not bad else bad)
print('ROOT_CAUSE ->', rc, hyp[rc]['state'])
from datetime import datetime
s = doc['investigation']['started']; c = doc['investigation']['concluded']
d = (c - s).total_seconds() if hasattr(c,'year') else None
print('WALL_CLOCK: declared', doc['usage']['wall_clock_seconds'], '| actual', d)
"
